+        './common/jiraHelpers.js': { extractTicketKey: function(p) { return p.ticket.key; } },
+        './configLoader.js': { loadProjectConfig: function() { return cfg; } },
+        './common/gitStaging.js': { buildExclusionPathspecs: function() { return ':!factory-kit'; } },
