/**
 * Move To In Testing Action (postJSAction for test_cases_generator)
 * Moves the ticket to "In Testing" status after test cases are generated.
 */

const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        const ticketKey = params.ticket ? params.ticket.key : null;
        if (!ticketKey) {
            return { success: false, error: 'No ticket key found in params' };
        }
        const projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        const jiraConfig = projectConfig.jira;
        var tracker = trackersModule.createTracker(projectConfig, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        console.log('Moving ' + ticketKey + ' to ' + jiraConfig.statuses.IN_TESTING);

        tracker.moveToStatus(ticketKey, jiraConfig.statuses.IN_TESTING);

        try {
            tracker.removeLabel(ticketKey, 'sm_test_cases_triggered');
        } catch (e) {
            console.log('Label sm_test_cases_triggered not found or already removed');
        }

        console.log('✅ ' + ticketKey + ' moved to ' + jiraConfig.statuses.IN_TESTING);

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, tracker: tracker });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return {
            success: true,
            message: ticketKey + ' moved to ' + jiraConfig.statuses.IN_TESTING
        };

    } catch (error) {
        console.error('❌ Error in moveToInTesting:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Move To Ready For Testing Action (postJSAction for test_cases_generator)
 * Moves the ticket to "Ready For Testing" status after test cases are generated.
 */

const configLoader = require('./configLoader.js');
const trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        const ticketKey = params.ticket ? params.ticket.key : null;
        if (!ticketKey) {
            return { success: false, error: 'No ticket key found in params' };
        }
        const projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        const jiraConfig = projectConfig.jira;
        var tracker = trackersModule.createTracker(projectConfig, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        console.log('Moving ' + ticketKey + ' to ' + jiraConfig.statuses.READY_FOR_TESTING);

        tracker.moveToStatus(ticketKey, jiraConfig.statuses.READY_FOR_TESTING);

        console.log('✅ ' + ticketKey + ' moved to ' + jiraConfig.statuses.READY_FOR_TESTING);

        return {
            success: true,
            message: ticketKey + ' moved to ' + jiraConfig.statuses.READY_FOR_TESTING
        };

    } catch (error) {
        console.error('❌ Error in moveToReadyForTesting:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Trigger Story Test Automation
 * Post-action for test_cases_generator.
 * Keeps the Story in Ready For Testing and immediately triggers story_test_automation.
 */

var autoStart = require('./common/autoStart.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        const storyKey = params.ticket.key;
        const config = params.jobParams && params.jobParams.config
            ? params.jobParams.config
            : (params.config || {});
        const customParams = (params.jobParams && params.jobParams.customParams) || params.customParams || {};

        var tracker = trackersModule.createTracker(config, customParams);

        console.log('=== Triggering story test automation for', storyKey, '===');

        var triggered = false;
        if (customParams.autoStartStoryTestAutomation && customParams.autoStartStoryTestAutomationConfigFile) {
            triggered = autoStart.triggerConfiguredWorkflowForTicket({
                ticketKey: storyKey,
                customParams: customParams,
                config: config,
                configFile: customParams.autoStartStoryTestAutomationConfigFile,
                label: 'story_test_automation',
                stripKeys: [
                    'removeLabel',
                    'autoStartStoryTestAutomation',
                    'autoStartStoryTestAutomationConfigFile'
                ]
            });
        }

        if (!triggered) {
            console.log('Story test automation not triggered via autoStart; asking SM to re-evaluate.');
            autoStart.triggerSmIfIdle({ config: config, customParams: customParams });
        } else {
            console.log('✅ Triggered story_test_automation for', storyKey);
        }

        // Remove the SM trigger label so test_cases_generator does not keep re-running
        const smTriggerLabel = customParams.removeLabel || 'sm_test_cases_triggered';
        try {
            tracker.removeLabel(storyKey, smTriggerLabel);
            console.log('✅ Removed SM trigger label:', smTriggerLabel);
        } catch (e) {
            console.warn('Failed to remove SM trigger label:', e);
        }

        // Post token usage summary comments from the test-case generation run
        try {
            tokenUsageComment.postTokenUsageComments(storyKey, { initiator: params.initiator, tracker: tracker });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return { success: true, triggered: triggered, storyKey: storyKey };

    } catch (error) {
        console.error('❌ Error in triggerStoryTestAutomation:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

