/**
 * Commit and Push To Base Branch Action
 *
 * Generic postJSAction for direct-to-main iteration loops (no branch, no PR).
 * Useful for content/artifact repos where the deliverable is deployed
 * automatically from the default branch (e.g. static-site pipelines) and the
 * agent should publish immediately.
 *
 * Steps:
 * 1. If the working tree is clean — post an optional "no changes" comment and finish.
 * 2. Optional pre-push gate command (customParams.directPush.gateCommand) run in
 *    workingDir; when it fails, nothing is pushed and the output is commented.
 * 3. git add -A, commit, pull --rebase, push to baseBranch.
 * 4. Optional Jira comment with customParams.directPush.successComment
 *    (supports {ticketKey} and {url} placeholders; url comes from
 *    customParams.directPush.resultUrlTemplate, also with {ticketKey}).
 *
 * Configuration (customParams.directPush):
 *   - commitMessage:    e.g. "Update {ticketKey} artifacts"
 *   - gateCommand:      e.g. "bash scripts/gate.sh {ticketKey}" (optional,
 *                       supports {ticketKey}). Must be a SINGLE plain command —
 *                       the executor rejects shell metacharacters
 *                       (&&, ||, |, ;, >, <). Wrap logic in a script file.
 *   - resultUrlTemplate: e.g. "https://example.com/{ticketKey}/" (optional)
 *   - successComment:   comment posted on success (optional)
 *   - noChangesComment: comment posted when nothing changed (optional)
 */

const { extractTicketKey } = require('./common/jiraHelpers.js');
var configLoader = require('./configLoader.js');
var gitStaging = require('./common/gitStaging.js');
var trackersModule = require('./common/trackers.js');

var _workingDir = null;
var _tracker = null;
function runCmd(args) {
    if (_workingDir) args.workingDirectory = _workingDir;
    return cli_execute_command(args);
}

function cleanCommandOutput(output) {
    if (!output) return '';
    return output.split('\n').filter(function (line) {
        return line.indexOf('Script started') === -1 &&
               line.indexOf('Script done') === -1 &&
               line.indexOf('COMMAND=') === -1 &&
               line.indexOf('COMMAND_EXIT_CODE=') === -1;
    }).join('\n').trim();
}

function render(template, ticketKey) {
    var url = '';
    if (template && template.resultUrlTemplate) {
        url = template.resultUrlTemplate.split('{ticketKey}').join(ticketKey);
    }
    return (template && template.text ? template.text : '')
        .split('{ticketKey}').join(ticketKey)
        .split('{url}').join(url);
}

function postComment(ticketKey, message) {
    try {
        _tracker.postComment(ticketKey, message);
    } catch (e) {
        console.warn('commitAndPushToBaseBranch: comment failed:', e.toString());
    }
}

function action(params) {
    var ticketKey = extractTicketKey(params) || (params.ticket && params.ticket.key);
    if (!ticketKey) {
        console.error('commitAndPushToBaseBranch: could not determine ticket key');
        return false;
    }

    var config = configLoader.loadProjectConfig(params.jobParams || params);
    _workingDir = config.workingDir || null;
    _tracker = trackersModule.createTracker(config, config.customParams || (params.jobParams && params.jobParams.customParams) || params.customParams || {});
    var baseBranch = (config.git && config.git.baseBranch) || 'main';
    var opts = (config.customParams && config.customParams.directPush) || {};

    try {
        var status = cleanCommandOutput(runCmd({ command: 'git status --porcelain' }));
        if (!status) {
            console.log('commitAndPushToBaseBranch: no changes to commit');
            if (opts.noChangesComment) {
                postComment(ticketKey, render({ text: opts.noChangesComment, resultUrlTemplate: opts.resultUrlTemplate }, ticketKey));
            }
            return true;
        }

        if (opts.gateCommand) {
            // NOTE: cli_execute_command rejects shell metacharacters
            // (&&, ||, |, ;, >, <, ...). gateCommand must be a single plain
            // invocation — wrap any logic into a script in the target repo
            // (e.g. "bash scripts/gate.sh {ticketKey}").
            var gateCmd = opts.gateCommand.split('{ticketKey}').join(ticketKey);
            try {
                var gateOut = cleanCommandOutput(runCmd({ command: gateCmd }));
                console.log('commitAndPushToBaseBranch: gate passed. ' + gateOut);
            } catch (gateError) {
                console.error('commitAndPushToBaseBranch: gate failed, not pushing:', gateError.toString());
                postComment(ticketKey, 'Pre-push gate failed, changes NOT pushed:\n\n```\n' + gateError.toString().slice(-1500) + '\n```');
                return false;
            }
        }

        var message = (opts.commitMessage || 'Update {ticketKey} artifacts').split('{ticketKey}').join(ticketKey);
        // `:!factory-kit` — nested machine-infra gitlink must not die on add -A (#648 class).
        // gh-1164: probe-filtered — naming an existing gitignored factory-kit in ANY
        // pathspec (exclusions included) trips git add's ignored-pathspec guard.
        runCmd({ command: 'git add -A -- ' + gitStaging.buildExclusionPathspecs(['factory-kit'], runCmd) });
        runCmd({ command: 'git commit -m "' + message.replace(/"/g, '\\"') + '" --no-verify' });
        runCmd({ command: 'git pull --rebase origin ' + baseBranch });
        runCmd({ command: 'git push origin HEAD:' + baseBranch });
        console.log('commitAndPushToBaseBranch: pushed to ' + baseBranch);

        if (opts.successComment) {
            postComment(ticketKey, render({ text: opts.successComment, resultUrlTemplate: opts.resultUrlTemplate }, ticketKey));
        }
        return true;
    } catch (e) {
        console.error('commitAndPushToBaseBranch failed:', e.toString());
        postComment(ticketKey, 'Push to ' + baseBranch + ' failed: ' + e.toString().slice(0, 1000));
        return false;
    }
}

if (typeof module !== 'undefined') {
    module.exports = { action: action };
}

/**
 * Move To Done Action (postJSAction for bug_test_cases_generator)
 * After test cases are generated for a bug, move the bug directly to Done.
 * If tests fail later, AI creates a new bug instead of re-opening this one.
 */

const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        const ticketKey = params.ticket ? params.ticket.key : null;
        if (!ticketKey) {
            return { success: false, error: 'No ticket key found in params' };
        }
        const projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        const jiraConfig = projectConfig.jira;
        var tracker = trackersModule.createTracker(projectConfig, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        console.log('Moving ' + ticketKey + ' to ' + jiraConfig.statuses.DONE + ' (bug with test cases generated)');

        tracker.moveToStatus(ticketKey, jiraConfig.statuses.DONE);

        try {
            tracker.removeLabel(ticketKey, 'sm_bug_test_cases_triggered');
        } catch (e) {
            console.log('Label sm_bug_test_cases_triggered not found or already removed');
        }

        tracker.postComment(ticketKey, 'Test cases generated. Bug marked as Done. If regression is detected, a new bug will be created automatically.');

        console.log('✅ ' + ticketKey + ' moved to ' + jiraConfig.statuses.DONE);

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, tracker: tracker });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return {
            success: true,
            message: ticketKey + ' moved to ' + jiraConfig.statuses.DONE
        };

    } catch (error) {
        console.error('❌ Error in moveToDone:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Move To In Testing Action (postJSAction for test_cases_generator)
 * Moves the ticket to "In Testing" status after test cases are generated.
 */

const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        const ticketKey = params.ticket ? params.ticket.key : null;
        if (!ticketKey) {
            return { success: false, error: 'No ticket key found in params' };
        }
        const projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        const jiraConfig = projectConfig.jira;
        var tracker = trackersModule.createTracker(projectConfig, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        console.log('Moving ' + ticketKey + ' to ' + jiraConfig.statuses.IN_TESTING);

        tracker.moveToStatus(ticketKey, jiraConfig.statuses.IN_TESTING);

        try {
            tracker.removeLabel(ticketKey, 'sm_test_cases_triggered');
        } catch (e) {
            console.log('Label sm_test_cases_triggered not found or already removed');
        }

        console.log('✅ ' + ticketKey + ' moved to ' + jiraConfig.statuses.IN_TESTING);

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, tracker: tracker });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return {
            success: true,
            message: ticketKey + ' moved to ' + jiraConfig.statuses.IN_TESTING
        };

    } catch (error) {
        console.error('❌ Error in moveToInTesting:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Move To Ready For Testing Action (postJSAction for test_cases_generator)
 * Moves the ticket to "Ready For Testing" status after test cases are generated.
 */

const configLoader = require('./configLoader.js');
const trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        const ticketKey = params.ticket ? params.ticket.key : null;
        if (!ticketKey) {
            return { success: false, error: 'No ticket key found in params' };
        }
        const projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        const jiraConfig = projectConfig.jira;
        var tracker = trackersModule.createTracker(projectConfig, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        console.log('Moving ' + ticketKey + ' to ' + jiraConfig.statuses.READY_FOR_TESTING);

        tracker.moveToStatus(ticketKey, jiraConfig.statuses.READY_FOR_TESTING);

        console.log('✅ ' + ticketKey + ' moved to ' + jiraConfig.statuses.READY_FOR_TESTING);

        return {
            success: true,
            message: ticketKey + ' moved to ' + jiraConfig.statuses.READY_FOR_TESTING
        };

    } catch (error) {
        console.error('❌ Error in moveToReadyForTesting:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Trigger Story Test Automation
 * Post-action for test_cases_generator.
 * Keeps the Story in Ready For Testing and immediately triggers story_test_automation.
 */

var autoStart = require('./common/autoStart.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        const storyKey = params.ticket.key;
        const config = params.jobParams && params.jobParams.config
            ? params.jobParams.config
            : (params.config || {});
        const customParams = (params.jobParams && params.jobParams.customParams) || params.customParams || {};

        var tracker = trackersModule.createTracker(config, customParams);

        console.log('=== Triggering story test automation for', storyKey, '===');

        var triggered = false;
        if (customParams.autoStartStoryTestAutomation && customParams.autoStartStoryTestAutomationConfigFile) {
            triggered = autoStart.triggerConfiguredWorkflowForTicket({
                ticketKey: storyKey,
                customParams: customParams,
                config: config,
                configFile: customParams.autoStartStoryTestAutomationConfigFile,
                label: 'story_test_automation',
                stripKeys: [
                    'removeLabel',
                    'autoStartStoryTestAutomation',
                    'autoStartStoryTestAutomationConfigFile'
                ]
            });
        }

        if (!triggered) {
            console.log('Story test automation not triggered via autoStart; asking SM to re-evaluate.');
            autoStart.triggerSmIfIdle({ config: config, customParams: customParams });
        } else {
            console.log('✅ Triggered story_test_automation for', storyKey);
        }

        // Remove the SM trigger label so test_cases_generator does not keep re-running
        const smTriggerLabel = customParams.removeLabel || 'sm_test_cases_triggered';
        try {
            tracker.removeLabel(storyKey, smTriggerLabel);
            console.log('✅ Removed SM trigger label:', smTriggerLabel);
        } catch (e) {
            console.warn('Failed to remove SM trigger label:', e);
        }

        // Post token usage summary comments from the test-case generation run
        try {
            tokenUsageComment.postTokenUsageComments(storyKey, { initiator: params.initiator, tracker: tracker });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return { success: true, triggered: triggered, storyKey: storyKey };

    } catch (error) {
        console.error('❌ Error in triggerStoryTestAutomation:', error);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

